cypress_script:
describe('HTTP Status Codes Page', () => {
  it('should navigate to the 200 status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.contains('200').click();
    cy.url().should('include', 'status_codes/200');
  });

  it('should not change URL when clicking an invalid link', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('#flash-messages').should('be.visible');
    cy.contains('here').click();
    cy.url().should('not.include', 'status_codes');
    cy.get('#flash-messages').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('HTTP Status Codes Page', () => {
  test('should navigate to the 200 status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=200');
    await expect(page).toHaveURL(/status_codes\/200/);
  });

  test('should not change URL when clicking an invalid link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await expect(page.locator('#flash-messages')).toBeVisible();
    await page.click('text=here');
    await expect(page).not.toHaveURL(/status_codes/);
    await expect(page.locator('#flash-messages')).toBeVisible();
  });
});
